namespace SqlSource.Generation.Emitting;

/// <summary>
/// The text that every file the generator writes for a type or a model shares.
/// </summary>
internal static class GeneratedText
{
    /// <summary>
    /// The lines that start a generated file: <c>// &lt;auto-generated/&gt;</c> and <c>#nullable enable</c>, each with
    /// <c>\n</c> after it.
    /// </summary>
    public const string Header = "// <auto-generated/>\n#nullable enable\n";

    /// <summary>One level of indentation, four spaces.</summary>
    public const string Indent = "    ";
}
